fun local(): Hlc {
    val l = maxOf(last.l, physical())
    val c = if (l == last.l) last.c + 1 else 0
    return set(l, c)
}

fun receive(m: Hlc): Hlc {
    val l = maxOf(last.l, m.l, physical())
    val c = when {
        l == last.l && l == m.l -> maxOf(last.c, m.c) + 1
        l == last.l -> last.c + 1
        l == m.l -> m.c + 1
        else -> 0
    }
    return set(l, c)
}
// a clock that steps back loses the max: l stays where it was and c counts up until the clock catches up
